Def roman_to_int(s: str) -> int:
    values = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000
    }
    result = 0
    prev = None
    for char in s[::-1]:
        if prev is None:
            prev = values[char]
        elif char in ['I', 'X', 'C'] and char < prev:
            return 0
        elif char in ['IV', 'IX', 'XL', 'XC', 'CD', 'CM']:
            result += values[char]
        else:
            result += values[char]
            prev = values[char]
    return result

